// Karate fighter sprites — 50 wide × 50 tall grid units
// d=black, o=orange(skin), w=white(gi), e=grey(gi shadow/fold), _=transparent
// Fighter faces RIGHT by default; left-facing is auto-flipped in fighter.js

// pad a 20-cell row to 50 cells (15 blank on each side)
function p(row) { return [...Array(15).fill('_'), ...row, ...Array(15).fill('_')]; }
const E = p(Array(20).fill('_')); // blank 50-cell row

